-- Corrective, self-healing re-seed of every system dashboard's latest
-- revision. A bug in reseedSystemDashboards (introduced in 697c96f, removed
-- in a later commit) briefly regenerated system dashboards from
-- packages/db/seeds/dashboards.sql on every demo reset — a frozen snapshot
-- from before 0034_demonstration_datasources_postgres.sql through
-- 0040_vue_architecture_applicative_datasource_postgres.sql converted each
-- dashboard's queries to the native Postgres datasource, so every reset
-- silently reintroduced the pre-conversion architecture-neo4j queries those
-- migrations had already retired. This re-applies the correct, current
-- Postgres-backed definitions (dumped from a database migrated from
-- scratch, i.e. unaffected by that bug) as a new latest revision on top of
-- whatever revision each dashboard is currently on — safe regardless of
-- whether the target already has the correct data or the corrupted one.

INSERT INTO "dashboard_revisions" ("dashboard_id", "revision", "definition", "created_by_id")
SELECT dd."id", COALESCE((SELECT MAX(rv."revision") FROM "dashboard_revisions" rv WHERE rv."dashboard_id" = dd."id"), 0) + 1, $fix_demonstration_datasources${"id":"demonstration-datasources","title":"Démonstration des datasources","panels":[{"id":"elements-postgres","panel":{"query":{"text":"SELECT count(*)::integer AS count FROM elements e JOIN workspaces w ON w.id = e.workspace_id WHERE w.organization_id = $organizationId","language":"sql","datasourceId":"postgres-app-db"},"title":"Éléments","parameters":[],"resultType":"metrics","description":"Nombre total d’éléments ArchiMate, compté via les tables PostgreSQL natives « elements »/« workspaces ».","visualization":{"max":1000,"type":"core/metric"}},"layout":{"x":0,"y":0,"width":6,"height":3},"parameterBindings":{}},{"id":"fournisseurs-postgres","panel":{"query":{"text":"SELECT count(*)::integer AS count FROM fournisseurs WHERE organization_id = $organizationId AND actif = $actif","language":"sql","datasourceId":"postgres-app-db"},"title":"Fournisseurs actifs (démonstration PostgreSQL)","parameters":[{"name":"actif","type":"boolean","label":"Fournisseurs actifs","required":false,"defaultValue":true}],"resultType":"metrics","description":"Métrique issue de la table PostgreSQL « fournisseurs » de l’organisation active.","visualization":{"type":"core/metric"}},"layout":{"x":6,"y":0,"width":6,"height":3},"parameterBindings":{}}],"category":"Démonstration","createdAt":"2026-08-07T20:00:00.000Z","createdBy":"codex","updatedAt":"2026-08-17T01:00:00.000Z","updatedBy":"system","parameters":[],"description":"Deux panneaux PostgreSQL : une agrégation sur les tables ArchiMate natives (elements/workspaces) et une autre sur la table de démonstration « fournisseurs ».","schemaVersion":2}$fix_demonstration_datasources$::jsonb, 'system'
FROM "dashboards" dd
WHERE dd."dashboard_id" = 'demonstration-datasources' AND dd."workspace_id" IS NULL;
--> statement-breakpoint

UPDATE "dashboards"
SET "latest_revision" = (SELECT MAX("revision") FROM "dashboard_revisions" WHERE "dashboard_id" = "dashboards"."id")
WHERE "dashboard_id" = 'demonstration-datasources' AND "workspace_id" IS NULL;
