SELECT dd."id", COALESCE((SELECT MAX(rv."revision") FROM "dashboard_revisions" rv WHERE rv."dashboard_id" = dd."id"), 0) + 1, $fix_principles${"id":"principles","title":"Chaîne de conformité par principe","panels":[{"id":"chaine-conformite","panel":{"query":{"text":"SELECT \"nodeIds\", \"emphasizedId\"\nFROM (\n  WITH principal AS (\n    SELECT e.uuid AS node_id\n    FROM elements e\n    JOIN workspaces w ON w.id = e.workspace_id\n    WHERE w.organization_id = $organizationId AND e.uuid = $principleId AND e.type = 'Principle'\n  ),\n  requirements AS (\n    SELECT DISTINCT ne.uuid AS node_id\n    FROM principal p\n    JOIN relationships r ON r.source_uuid = p.node_id OR r.target_uuid = p.node_id\n    JOIN workspaces rw ON rw.id = r.workspace_id\n    JOIN elements ne ON ne.uuid = CASE WHEN r.source_uuid = p.node_id THEN r.target_uuid ELSE r.source_uuid END\n    JOIN workspaces nw ON nw.id = ne.workspace_id\n    WHERE rw.organization_id = $organizationId\n      AND nw.organization_id = $organizationId\n      AND ne.type = 'Requirement'\n  ),\n  constraint_pairs AS (\n    SELECT DISTINCT req.node_id AS requirement_id, ce.uuid AS constraint_id\n    FROM requirements req\n    JOIN relationships r ON r.source_uuid = req.node_id OR r.target_uuid = req.node_id\n    JOIN workspaces rw ON rw.id = r.workspace_id\n    JOIN elements ce ON ce.uuid = CASE WHEN r.source_uuid = req.node_id THEN r.target_uuid ELSE r.source_uuid END\n    JOIN workspaces cw ON cw.id = ce.workspace_id\n    WHERE rw.organization_id = $organizationId\n      AND cw.organization_id = $organizationId\n      AND ce.type = 'Constraint'\n  )\n  SELECT\n    CASE\n      WHEN EXISTS (SELECT 1 FROM constraint_pairs) THEN (\n        SELECT array_agg(DISTINCT node_id) FROM (\n          SELECT node_id FROM principal\n          UNION SELECT requirement_id FROM constraint_pairs\n          UNION SELECT constraint_id FROM constraint_pairs\n        ) unioned\n      )\n      ELSE (\n        SELECT array_agg(DISTINCT node_id) FROM (\n          SELECT node_id FROM principal\n          UNION SELECT node_id FROM requirements\n        ) unioned\n      )\n    END AS \"nodeIds\",\n    (SELECT node_id FROM principal) AS \"emphasizedId\"\n  WHERE EXISTS (SELECT 1 FROM principal)\n) AS reachable","language":"sql","datasourceId":"postgres-app-db"},"title":"Chaîne de conformité par principe","parameters":[{"name":"principleId","type":"string","label":"Principe","required":true,"selector":{"source":"model-elements","elementTypes":["Principle"]}}],"resultType":"graph","description":"Affiche le principe sélectionné et les exigences et contraintes qui lui sont reliées.","visualization":{"type":"graph","colorByProperty":"type"}},"layout":{"x":0,"y":0,"width":12,"height":8},"parameterBindings":{"principleId":{"source":"dashboard","parameter":"principleId"}}}],"category":"Motivation","createdAt":"2026-08-07T00:00:00.000Z","createdBy":"christophe.lacombe","updatedAt":"2026-08-17T03:00:00.000Z","updatedBy":"system","parameters":[{"name":"principleId","type":"string","label":"Principe","required":true,"selector":{"source":"model-elements","elementTypes":["Principle"]}}],"description":"Affiche le principe sélectionné et les exigences et contraintes qui lui sont reliées.","schemaVersion":2}$fix_principles$::jsonb, 'system'
FROM "dashboards" dd
WHERE dd."dashboard_id" = 'principles' AND dd."workspace_id" IS NULL;
