SELECT dd."id", COALESCE((SELECT MAX(rv."revision") FROM "dashboard_revisions" rv WHERE rv."dashboard_id" = dd."id"), 0) + 1, $fix_rapports_architecture${"id":"rapports-architecture","title":"Rapports d’Architecture","panels":[{"id":"elements","panel":{"query":{"text":"SELECT count(*)::integer AS count\nFROM elements e\nJOIN workspaces w ON w.id = e.workspace_id\nWHERE w.organization_id = $organizationId","language":"sql","datasourceId":"postgres-app-db"},"title":"Éléments","parameters":[],"resultType":"metrics","description":"Nombre total d’éléments ArchiMate affiché par le plugin d’exemple.","visualization":{"max":1000,"type":"core/metric"}},"layout":{"x":0,"y":0,"width":3,"height":3},"parameterBindings":{}},{"id":"relations","panel":{"query":{"text":"SELECT count(*)::integer AS count\nFROM relationships r\nJOIN workspaces w ON w.id = r.workspace_id\nWHERE w.organization_id = $organizationId","language":"sql","datasourceId":"postgres-app-db"},"title":"Relations","parameters":[],"resultType":"metrics","description":"Nombre total de relations ArchiMate.","visualization":{"type":"metric"}},"layout":{"x":3,"y":0,"width":3,"height":3},"parameterBindings":{}},{"id":"vues","panel":{"query":{"text":"SELECT count(*)::integer AS count\nFROM views v\nJOIN workspaces w ON w.id = v.workspace_id\nWHERE w.organization_id = $organizationId","language":"sql","datasourceId":"postgres-app-db"},"title":"Vues","parameters":[],"resultType":"metrics","description":"Nombre total de vues ArchiMate.","visualization":{"type":"metric"}},"layout":{"x":6,"y":0,"width":3,"height":3},"parameterBindings":{}},{"id":"couches","panel":{"query":{"text":"SELECT count(DISTINCT (CASE\n    WHEN e.type LIKE 'Business%' OR e.type IN ('Contract', 'Representation', 'Product') THEN 'Business'\n    WHEN e.type LIKE 'Application%' OR e.type = 'DataObject' THEN 'Application'\n    WHEN e.type LIKE 'Technology%' OR e.type IN ('Node', 'Device', 'SystemSoftware', 'Path', 'CommunicationNetwork', 'Artifact') THEN 'Technology'\n    WHEN e.type IN ('Equipment', 'Facility', 'DistributionNetwork', 'Material') THEN 'Physical'\n    WHEN e.type IN ('Stakeholder', 'Driver', 'Assessment', 'Goal', 'Outcome', 'Principle', 'Requirement', 'Constraint', 'Meaning', 'Value') THEN 'Motivation'\n    WHEN e.type IN ('Resource', 'Capability', 'CourseOfAction', 'ValueStream') THEN 'Strategy'\n    WHEN e.type IN ('WorkPackage', 'Deliverable', 'ImplementationEvent', 'Plateau', 'Gap') THEN 'Implementation'\n    ELSE 'Composite'\n  END))::integer AS count\nFROM elements e\nJOIN workspaces w ON w.id = e.workspace_id\nWHERE w.organization_id = $organizationId","language":"sql","datasourceId":"postgres-app-db"},"title":"Couches ArchiMate","parameters":[],"resultType":"metrics","description":"Nombre de couches présentes dans le modèle.","visualization":{"type":"metric"}},"layout":{"x":9,"y":0,"width":3,"height":3},"parameterBindings":{}}],"category":"Architecture","createdAt":"2026-08-07T16:30:00.000Z","createdBy":"christophe.lacombe","updatedAt":"2026-08-17T03:00:00.000Z","updatedBy":"system","parameters":[],"description":"Vue d’ensemble du modèle ArchiMate courant.","schemaVersion":2}$fix_rapports_architecture$::jsonb, 'system'
FROM "dashboards" dd
WHERE dd."dashboard_id" = 'rapports-architecture' AND dd."workspace_id" IS NULL;
--> statement-breakpoint

UPDATE "dashboards"
SET "latest_revision" = (SELECT MAX("revision") FROM "dashboard_revisions" WHERE "dashboard_id" = "dashboards"."id")
WHERE "dashboard_id" = 'rapports-architecture' AND "workspace_id" IS NULL;
