INSERT INTO "dashboard_revisions" ("dashboard_id", "revision", "definition", "created_by_id")
SELECT dd."id", COALESCE((SELECT MAX(rv."revision") FROM "dashboard_revisions" rv WHERE rv."dashboard_id" = dd."id"), 0) + 1, $fix_voisinage_elements${"id":"voisinage-elements","title":"Voisinage des éléments","panels":[{"id":"graphe-voisinage","panel":{"query":{"text":"SELECT\n  (\n    SELECT array_agg(DISTINCT node_id) FROM (\n      SELECT e.uuid AS node_id\n      UNION\n      SELECT node_id FROM (\n        SELECT ne.uuid AS node_id\n        FROM relationships r\n        JOIN workspaces rw ON rw.id = r.workspace_id\n        JOIN elements ne ON ne.uuid = CASE WHEN r.source_uuid = e.uuid THEN r.target_uuid ELSE r.source_uuid END\n        JOIN workspaces nw ON nw.id = ne.workspace_id\n        WHERE (r.source_uuid = e.uuid OR r.target_uuid = e.uuid)\n          AND rw.organization_id = $organizationId\n          AND nw.organization_id = $organizationId\n          AND r.type IN ('Composition', 'Aggregation', 'Assignment', 'Realization', 'Serving', 'Access', 'Influence', 'Triggering', 'Flow', 'Specialization', 'Association')\n        ORDER BY ne.uuid\n        LIMIT 100\n      ) neighbors\n    ) all_nodes\n  ) AS \"nodeIds\",\n  e.uuid AS \"emphasizedId\"\nFROM elements e\nJOIN workspaces w ON w.id = e.workspace_id\nWHERE w.organization_id = $organizationId AND e.uuid = $elementId","language":"sql","datasourceId":"postgres-app-db"},"title":"Voisinage de l’élément","parameters":[{"name":"elementId","type":"string","label":"Élément","required":true}],"resultType":"graph","description":"Relations directes de l’élément sélectionné, dans les deux sens.","visualization":{"type":"graph"}},"layout":{"x":0,"y":0,"width":12,"height":8},"parameterBindings":{"elementId":{"source":"dashboard","parameter":"elementId"}}},{"id":"proprietes","panel":{"query":{"text":"SELECT COALESCE(\n  (\n    SELECT jsonb_agg(jsonb_build_object('Nom', pd.name, 'Valeur', ep.value) ORDER BY pd.name)\n    FROM element_properties ep\n    JOIN property_definitions pd ON pd.uuid = ep.property_def_uuid AND pd.workspace_id = e.workspace_id\n    WHERE ep.element_id = e.id\n  ),\n  '[]'::jsonb\n) AS rows\nFROM elements e\nJOIN workspaces w ON w.id = e.workspace_id\nWHERE w.organization_id = $organizationId AND e.uuid = $elementId","language":"sql","datasourceId":"postgres-app-db"},"title":"Propriétés","parameters":[{"name":"elementId","type":"string","label":"Élément","required":true}],"resultType":"table","description":"Propriétés ArchiMate de l’élément sélectionné.","visualization":{"type":"table"}},"layout":{"x":0,"y":8,"width":12,"height":5},"parameterBindings":{"elementId":{"source":"dashboard","parameter":"elementId"}}},{"id":"relations","panel":{"query":{"text":"SELECT COALESCE(\n  (\n    SELECT jsonb_agg(jsonb_build_object(\n      'Direction', CASE WHEN r.source_uuid = e.uuid THEN 'Sortante' ELSE 'Entrante' END,\n      'Relation', r.type,\n      'Élément', oe.name,\n      'Type', oe.type,\n      'Couche', (CASE\n    WHEN oe.type LIKE 'Business%' OR oe.type IN ('Contract', 'Representation', 'Product') THEN 'Business'\n    WHEN oe.type LIKE 'Application%' OR oe.type = 'DataObject' THEN 'Application'\n    WHEN oe.type LIKE 'Technology%' OR oe.type IN ('Node', 'Device', 'SystemSoftware', 'Path', 'CommunicationNetwork', 'Artifact') THEN 'Technology'\n    WHEN oe.type IN ('Equipment', 'Facility', 'DistributionNetwork', 'Material') THEN 'Physical'\n    WHEN oe.type IN ('Stakeholder', 'Driver', 'Assessment', 'Goal', 'Outcome', 'Principle', 'Requirement', 'Constraint', 'Meaning', 'Value') THEN 'Motivation'\n    WHEN oe.type IN ('Resource', 'Capability', 'CourseOfAction', 'ValueStream') THEN 'Strategy'\n    WHEN oe.type IN ('WorkPackage', 'Deliverable', 'ImplementationEvent', 'Plateau', 'Gap') THEN 'Implementation'\n    ELSE 'Composite'\n  END)\n    ))\n    FROM relationships r\n    JOIN workspaces rw ON rw.id = r.workspace_id\n    JOIN elements oe ON oe.uuid = CASE WHEN r.source_uuid = e.uuid THEN r.target_uuid ELSE r.source_uuid END\n    JOIN workspaces ow ON ow.id = oe.workspace_id\n    WHERE rw.organization_id = $organizationId\n      AND ow.organization_id = $organizationId\n      AND (r.source_uuid = e.uuid OR r.target_uuid = e.uuid)\n  ),\n  '[]'::jsonb\n) AS rows\nFROM elements e\nJOIN workspaces w ON w.id = e.workspace_id\nWHERE w.organization_id = $organizationId AND e.uuid = $elementId","language":"sql","datasourceId":"postgres-app-db"},"title":"Relations","parameters":[{"name":"elementId","type":"string","label":"Élément","required":true}],"resultType":"table","description":"Relations entrantes et sortantes de l’élément sélectionné.","visualization":{"type":"table","columnOrder":["Direction","Relation","Élément","Type","Couche"]}},"layout":{"x":0,"y":8,"width":12,"height":5},"parameterBindings":{"elementId":{"source":"dashboard","parameter":"elementId"}}}],"category":"Éléments","createdAt":"2026-08-07T00:00:00.000Z","createdBy":"christophe.lacombe","tabGroups":[{"id":"details-element","tabs":[{"id":"proprietes","title":"Propriétés","panelIds":["proprietes"]},{"id":"relations","title":"Relations","panelIds":["relations"]}]}],"updatedAt":"2026-08-17T03:00:00.000Z","updatedBy":"system","parameters":[{"name":"elementId","type":"string","label":"Élément","required":true,"selector":{"source":"model-elements","elementTypes":["Stakeholder","Driver","Assessment","Goal","Outcome","Principle","Requirement","Constraint","Meaning","Value","Resource","Capability","CourseOfAction","ValueStream","BusinessActor","BusinessRole","BusinessCollaboration","BusinessInterface","BusinessProcess","BusinessFunction","BusinessInteraction","BusinessEvent","BusinessService","BusinessObject","Contract","Representation","Product","ApplicationComponent","ApplicationCollaboration","ApplicationInterface","ApplicationFunction","ApplicationInteraction","ApplicationProcess","ApplicationEvent","ApplicationService","DataObject","Node","Device","SystemSoftware","TechnologyCollaboration","TechnologyInterface","Path","CommunicationNetwork","TechnologyFunction","TechnologyProcess","TechnologyInteraction","TechnologyEvent","TechnologyService","Artifact","Equipment","Facility","DistributionNetwork","Material","WorkPackage","Deliverable","ImplementationEvent","Plateau","Gap","Location","Grouping"]}}],"description":"Explorez les relations directes de l’élément sélectionné.","schemaVersion":2}$fix_voisinage_elements$::jsonb, 'system'
FROM "dashboards" dd
WHERE dd."dashboard_id" = 'voisinage-elements' AND dd."workspace_id" IS NULL;
--> statement-breakpoint

UPDATE "dashboards"
SET "latest_revision" = (SELECT MAX("revision") FROM "dashboard_revisions" WHERE "dashboard_id" = "dashboards"."id")
WHERE "dashboard_id" = 'voisinage-elements' AND "workspace_id" IS NULL;
