INSERT INTO "dashboard_revisions" ("dashboard_id", "revision", "definition", "created_by_id")
SELECT dd."id", COALESCE((SELECT MAX(rv."revision") FROM "dashboard_revisions" rv WHERE rv."dashboard_id" = dd."id"), 0) + 1, $fix_vue_architecture_applicative${"id":"vue-architecture-applicative","title":"Vue d’ensemble applicative","panels":[{"id":"composants-connectes","panel":{"query":{"text":"SELECT COALESCE(array_agg(node_id ORDER BY node_name ASC), ARRAY[]::text[]) AS \"nodeIds\"\nFROM (\n  SELECT DISTINCT target.uuid AS node_id, target.name AS node_name\n  FROM relationships r\n  JOIN workspaces rw ON rw.id = r.workspace_id\n  JOIN elements source_el ON source_el.uuid = r.source_uuid\n  JOIN workspaces sw ON sw.id = source_el.workspace_id\n  JOIN elements target ON target.uuid = r.target_uuid\n  JOIN workspaces tw ON tw.id = target.workspace_id\n  WHERE rw.organization_id = $organizationId\n    AND sw.organization_id = $organizationId\n    AND tw.organization_id = $organizationId\n    AND r.type = 'Flow'\n    AND source_el.type = 'ApplicationComponent'\n    AND target.type = 'ApplicationComponent'\n    AND target.name IS NOT NULL\n  ORDER BY target.name ASC\n  LIMIT 100\n) x","language":"sql","datasourceId":"postgres-app-db"},"title":"Composants applicatifs connectés par des flux","parameters":[],"resultType":"graph","description":"Composants applicatifs atteints par un flux direct depuis un autre composant applicatif.","visualization":{"type":"graph"}},"layout":{"x":0,"y":0,"width":9,"height":7},"parameterBindings":{}},{"id":"sans-documentation","panel":{"query":{"text":"SELECT count(*)::integer AS count\nFROM (\n  SELECT e.uuid\n  FROM elements e\n  JOIN workspaces w ON w.id = e.workspace_id\n  WHERE w.organization_id = $organizationId\n    AND e.type = 'ApplicationComponent'\n    AND e.description IS NULL\n  LIMIT 500\n) capped","language":"sql","datasourceId":"postgres-app-db"},"title":"Composants applicatifs sans documentation","parameters":[],"resultType":"metrics","description":"Nombre de composants applicatifs sans documentation renseignée.","visualization":{"type":"metric"}},"layout":{"x":9,"y":0,"width":3,"height":3},"parameterBindings":{}},{"id":"acteurs-servis","panel":{"query":{"text":"SELECT COALESCE(jsonb_agg(jsonb_build_object('id', node_id, 'name', node_name, 'type', node_type) ORDER BY node_name ASC), '[]'::jsonb) AS rows\nFROM (\n  SELECT DISTINCT target.uuid AS node_id, target.name AS node_name, target.type AS node_type\n  FROM relationships r\n  JOIN workspaces rw ON rw.id = r.workspace_id\n  JOIN elements source_el ON source_el.uuid = r.source_uuid\n  JOIN workspaces sw ON sw.id = source_el.workspace_id\n  JOIN elements target ON target.uuid = r.target_uuid\n  JOIN workspaces tw ON tw.id = target.workspace_id\n  WHERE rw.organization_id = $organizationId\n    AND sw.organization_id = $organizationId\n    AND tw.organization_id = $organizationId\n    AND r.type = 'Serving'\n    AND source_el.type = 'ApplicationComponent'\n    AND target.type = 'BusinessActor'\n    AND target.name IS NOT NULL\n    AND (CASE\n    WHEN target.type LIKE 'Business%' OR target.type IN ('Contract', 'Representation', 'Product') THEN 'Business'\n    WHEN target.type LIKE 'Application%' OR target.type = 'DataObject' THEN 'Application'\n    WHEN target.type LIKE 'Technology%' OR target.type IN ('Node', 'Device', 'SystemSoftware', 'Path', 'CommunicationNetwork', 'Artifact') THEN 'Technology'\n    WHEN target.type IN ('Equipment', 'Facility', 'DistributionNetwork', 'Material') THEN 'Physical'\n    WHEN target.type IN ('Stakeholder', 'Driver', 'Assessment', 'Goal', 'Outcome', 'Principle', 'Requirement', 'Constraint', 'Meaning', 'Value') THEN 'Motivation'\n    WHEN target.type IN ('Resource', 'Capability', 'CourseOfAction', 'ValueStream') THEN 'Strategy'\n    WHEN target.type IN ('WorkPackage', 'Deliverable', 'ImplementationEvent', 'Plateau', 'Gap') THEN 'Implementation'\n    ELSE 'Composite'\n  END) = $couche\n  ORDER BY target.name ASC\n  LIMIT 500\n) x","language":"sql","datasourceId":"postgres-app-db"},"title":"Acteurs métier servis par les composants applicatifs","parameters":[{"name":"couche","type":"enum","label":"Couche ArchiMate","required":false,"defaultValue":"Business","allowedValues":["Application","Business"]}],"resultType":"table","description":"Liste chaque composant applicatif et les acteurs métier qu'il sert directement.","visualization":{"type":"table"}},"layout":{"x":0,"y":7,"width":12,"height":5},"parameterBindings":{"couche":{"value":"Business","source":"constant"}}}],"category":"Applications","createdAt":"2026-08-07T00:00:00.000Z","createdBy":"christophe.lacombe","updatedAt":"2026-08-17T03:00:00.000Z","updatedBy":"system","parameters":[],"description":"Synthèse des composants applicatifs, de leur documentation et des acteurs métier servis.","schemaVersion":2}$fix_vue_architecture_applicative$::jsonb, 'system'
FROM "dashboards" dd
WHERE dd."dashboard_id" = 'vue-architecture-applicative' AND dd."workspace_id" IS NULL;
--> statement-breakpoint

UPDATE "dashboards"
SET "latest_revision" = (SELECT MAX("revision") FROM "dashboard_revisions" WHERE "dashboard_id" = "dashboards"."id")
WHERE "dashboard_id" = 'vue-architecture-applicative' AND "workspace_id" IS NULL;
--> statement-breakpoint
